const keyword = String($json.keyword || $json.search_query || '').trim();
const location = String($json.location || '').trim();

if (!keyword) {
  throw new Error('LINKEDIN_SEARCH_KEYWORD_MISSING');
}

if (!location) {
  throw new Error('LINKEDIN_LOCATION_MISSING');
}

return [{
  json: {
    ...$json,
    keyword,
    location
  }
}];

return items.map(item => {
  const data = item.json;

  return {
    json: {
      name: data.name ?? data.company_name ?? data.company ?? null,
      phone: data.phone ?? data.phone_number ?? null,
      email: data.email ?? null,
      website: data.website ?? data.company_website ?? null,
      source: 'linkedin_hiring_post'
    }
  };
});

const data = $json;

const hasResults = Array.isArray(data.results)
  ? data.results.length > 0
  : Object.keys(data).length > 0;

if (!hasResults) {
  return [{
    json: {
      ...data,
      success: false,
      error_type: 'NO_RESULTS',
      source: 'linkedin_hiring_post',
      results_count: 0
    }
  }];
}

return [{
  json: {
    ...data,
    success: true,
    error_type: null,
    source: 'linkedin_hiring_post'
  }
}];
